]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; }; const lines = ['品番,品名,発注数'].concat(rows.map(r => [r.code, r.name, r.order_qty].map(esc).join(','))); return { targets: rows, csv: lines.join('
') + '
