function main(i) { const q = String(i.question || '').replace(/[\s、。？?！!]/g, ''); const grams = (s) => { const out = new Set(); for (let k = 0; k < s.length - 1; k++) out.add(s.substr(k, 2)); return out; }; const qg = grams(q); const scored = (i.items || []).map((r) => { const fq = String(r.data.question || '').replace(/[\s、。？?！!]/g, ''); const fg = grams(fq); let hit = 0; fg.forEach((g) => { if (qg.has(g)) hit++; }); const score = fg.size ? hit / fg.size : 0; return { faq_no: r.data.faq_no, question: r.data.question, answer: r.data.answer, score }; }).filter((x) => x.score >= 0.5).sort((a, b) => b.score - a.score).slice(0, 5); return { hits: scored, found: scored.length > 0, faqs: scored.map((x) => `[番号 ${x.faq_no}] 質問: ${x.question}
回答: ${x.answer}`).join('

') }; }

